/* 以下地址范围适用于 x2600，其他 soc 请查看手册修改*/
#define NEMC0_ADDR_START 0x1b000000
#define NEMC0_ADDR_END 0x1b00ffff
#define NEMC1_ADDR_START 0x1a000000
#define NEMC1_ADDR_END 0x1a00ffff

enum nemc_burst_length {
    NEMC_BL_4,  //可用于 8/16 bit bus width
    NEMC_BL_8,  //可用于 8/16 bit bus width
    NEMC_BL_16, //可用于 8/16 bit bus width
    NEMC_BL_32, //仅用于 8 bit bus width
};

/*
无特殊说明，则为值对应相等的周期
tras: 值范围：0 ~ 15，11 对应的周期为 12， 12 对应 15， 13 对应 20，14 对应 25，15 对应 31
taw: 值范围：0 ~ 15，11 对应的周期为 12， 12 对应 15， 13 对应 20，14 对应 25，15 对应 31
twas: 值范围：0 ~ 15，11 对应的周期为 12， 12 对应 15， 13 对应 20，14 对应 25，15 对应 31
tbp: 值范围：0 ~ 15，11 对应的周期为 12， 12 对应 15， 13 对应 20，14 对应 25，15 对应 31
tch: 值范围：0 ~ 15
tavds: 值范围：0 ~ 15，仅 muxed memory 有效
tavdp: 值范围：0 ~ 15，仅 muxed memory 有效
tavdh: 值范围：0 ~ 15，仅 muxed memory 有效
strv: 值范围：0 ~ 63
is_double_timing：所有周期都将乘与 2，值范围：0：禁用，1：启用
*/
struct nemc_timing {
    uint8_t tras;
    uint8_t taw;
    uint8_t twas;
    uint8_t tbp;
    uint8_t tch;
    uint8_t tavds;
    uint8_t tavdp;
    uint8_t tavdh;
    uint8_t strv;
    enum nemc_burst_length bl;
    int is_double_timing;
};

enum nemc_mode {
    NORMAL_MODE,
    BURST_MODE,
    MUXED_MODE,
};

struct nemc_config
{
    int id;
    int data_width;
    int addr_width;
    int use_wait_pin;
    enum nemc_mode mode;
};

int nemc_init(struct nemc_config config, struct nemc_timing timing);

